//! The Modbus register map as data.
//!
//! The ADR calls this the contract the future RS-485 "duck" protocol
//! reuses, so the table lives here (one source), the server in granite-fw
//! reads values through [`discrete_inputs`], [`input_registers`],
//! [`holding_registers`] and [`coils`], writes come back as a
//! [`Command`] through [`command_from_holding`] / [`command_from_coil`],
//! and `firmware/docs/modbus_map.md` is generated by
//! [`render_markdown`].
//!
//! Register 14 of the input registers is the map version. Freeze the map
//! by bumping [`MAP_VERSION`] before any external integration.

use alloc::format;
use alloc::string::{String, ToString};
use core::fmt;

use crate::actuator::{ActionKind, ActionResult};
use crate::hal::TEMP_MISSING;
use crate::msg::{Args, Command, CommandKind};
use crate::node::NodeState;
use crate::observed::Observed;
use crate::{DRY_COUNT, NODE_COUNT, NodeId, PROBE_SLOTS, Target};

/// Version of this map, exposed in input register 14.
pub const MAP_VERSION: u16 = 1;

/// Number of discrete inputs.
pub const DISCRETE_COUNT: usize = 14;
/// Number of input registers.
pub const INPUT_COUNT: usize = 15;
/// Number of holding registers.
pub const HOLDING_COUNT: usize = 10;
/// Number of coils.
pub const COIL_COUNT: usize = NODE_COUNT;

/// Holding-register command words.
pub mod cmd_word {
    /// No command / cleared.
    pub const NONE: u16 = 0;
    /// `on`.
    pub const ON: u16 = 1;
    /// `off` (escalates like the MQTT command).
    pub const OFF: u16 = 2;
    /// `force_off`.
    pub const FORCE_OFF: u16 = 3;
    /// `reset`.
    pub const RESET: u16 = 4;
    /// `cycle`.
    pub const CYCLE: u16 = 5;
}

/// Bits of input register 13.
pub mod fault_bits {
    /// Expander readback mismatch or a blown press deadline.
    pub const EXPANDER: u16 = 1 << 0;
    /// The power LEDs could not be read.
    pub const SENSE: u16 = 1 << 1;
    /// A configured probe did not answer.
    pub const PROBE_MISSING: u16 = 1 << 2;
    /// VIN outside the configured window.
    pub const VIN: u16 = 1 << 3;
    /// An OTA image is pending validation.
    pub const OTA_PENDING: u16 = 1 << 4;
    /// A config section fell back to its defaults at boot.
    pub const CONFIG_FALLBACK: u16 = 1 << 5;
    /// The broker is configured but not connected.
    pub const MQTT_DOWN: u16 = 1 << 6;
}

/// What register 9 of the holding registers reports.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
#[repr(u16)]
pub enum ResultCode {
    /// Nothing has been commanded yet.
    #[default]
    Idle = 0,
    /// The last command finished successfully.
    Ok = 1,
    /// The last command is still running.
    Accepted = 2,
    /// The last command was refused.
    Refused = 3,
    /// The last command failed.
    Failed = 4,
    /// Soft-off is still pending on the node.
    ShutdownPending = 5,
}

impl ResultCode {
    /// Register value.
    pub const fn as_u16(self) -> u16 {
        self as u16
    }

    /// Map an action result onto a code.
    pub const fn of_result(r: &ActionResult) -> Self {
        match r {
            ActionResult::Ok => ResultCode::Ok,
            ActionResult::ShutdownPending => ResultCode::ShutdownPending,
            ActionResult::Refused { .. } => ResultCode::Refused,
            ActionResult::Failed { .. } => ResultCode::Failed,
        }
    }
}

/// Firmware version as the map reports it.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub struct FwVersion {
    /// Major.
    pub major: u8,
    /// Minor.
    pub minor: u8,
}

impl FwVersion {
    /// Packed `major << 8 | minor`.
    pub const fn as_u16(self) -> u16 {
        ((self.major as u16) << 8) | self.minor as u16
    }
}

/// Which table an entry belongs to.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum RegKind {
    /// Function 2, read only, one bit.
    DiscreteInput,
    /// Function 4, read only, 16 bits.
    InputRegister,
    /// Functions 3 / 6 / 16, read and write, 16 bits.
    HoldingRegister,
    /// Functions 1 / 5, read and write, one bit.
    Coil,
}

impl RegKind {
    /// Table name for the documentation.
    pub const fn as_str(self) -> &'static str {
        match self {
            RegKind::DiscreteInput => "Discrete inputs",
            RegKind::InputRegister => "Input registers",
            RegKind::HoldingRegister => "Holding registers",
            RegKind::Coil => "Coils",
        }
    }
}

/// Read / write permission of an entry.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Access {
    /// Read only.
    R,
    /// Read and write.
    Rw,
}

impl Access {
    /// Documentation string.
    pub const fn as_str(self) -> &'static str {
        match self {
            Access::R => "r",
            Access::Rw => "rw",
        }
    }
}

/// One row of the map.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct RegEntry {
    /// Which table.
    pub kind: RegKind,
    /// Address inside that table.
    pub addr: u16,
    /// Short identifier.
    pub name: &'static str,
    /// What it means.
    pub meaning: &'static str,
    /// Unit and scaling.
    pub scale: &'static str,
    /// Permission.
    pub access: Access,
}

const fn di(addr: u16, name: &'static str, meaning: &'static str) -> RegEntry {
    RegEntry {
        kind: RegKind::DiscreteInput,
        addr,
        name,
        meaning,
        scale: "0/1",
        access: Access::R,
    }
}

const fn ir(addr: u16, name: &'static str, meaning: &'static str, scale: &'static str) -> RegEntry {
    RegEntry {
        kind: RegKind::InputRegister,
        addr,
        name,
        meaning,
        scale,
        access: Access::R,
    }
}

const fn hr(addr: u16, name: &'static str, meaning: &'static str, scale: &'static str) -> RegEntry {
    RegEntry {
        kind: RegKind::HoldingRegister,
        addr,
        name,
        meaning,
        scale,
        access: Access::Rw,
    }
}

const fn co(addr: u16, name: &'static str, meaning: &'static str) -> RegEntry {
    RegEntry {
        kind: RegKind::Coil,
        addr,
        name,
        meaning,
        scale: "0/1",
        access: Access::Rw,
    }
}

