/// Look one entry up.
pub fn entry(kind: RegKind, addr: u16) -> Option<&'static RegEntry> {
    MAP.iter().find(|e| e.kind == kind && e.addr == addr)
}

/// Why a Modbus write could not be turned into a command.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum MapError {
    /// No such register in this table (Modbus exception 2).
    UnknownRegister {
        /// Which table.
        kind: RegKind,
        /// Which address.
        addr: u16,
    },
    /// The register exists but the value means nothing (exception 3).
    BadValue {
        /// Which address.
        addr: u16,
        /// What was written.
        value: u16,
    },
}

impl fmt::Display for MapError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            MapError::UnknownRegister { kind, addr } => {
                write!(f, "no {} at {addr}", kind.as_str())
            }
            MapError::BadValue { addr, value } => {
                write!(f, "value {value} is not valid for register {addr}")
            }
        }
    }
}

/// Discrete inputs, in address order.
pub fn discrete_inputs(o: &Observed) -> [bool; DISCRETE_COUNT] {
    let mut out = [false; DISCRETE_COUNT];
    for (i, bit) in out[..NODE_COUNT].iter_mut().enumerate() {
        *bit = o.node_led((i + 1) as NodeId) == Some(true);
    }
    for (i, bit) in out[NODE_COUNT..NODE_COUNT + DRY_COUNT]
        .iter_mut()
        .enumerate()
    {
        *bit = o.dry((i + 1) as u8) == Some(true);
    }
    out[12] = o.link_up.value;
    out[13] = o.mqtt_connected.value;
    out
}

/// Input registers, in address order.
pub fn input_registers(o: &Observed, fw: FwVersion, faults: u16) -> [u16; INPUT_COUNT] {
    let mut out = [0u16; INPUT_COUNT];
    for (slot, reg) in out[..PROBE_SLOTS].iter_mut().enumerate() {
        let centi = o
            .probe(slot)
            .and_then(|p| p.centi_c)
            .unwrap_or(TEMP_MISSING);
        *reg = centi as u16;
    }
    out[8] = o.board_temp.value.unwrap_or(TEMP_MISSING) as u16;
    out[9] = o.vin_mv.value.unwrap_or(0).min(u16::MAX as u32) as u16;
    out[10] = (o.uptime_s.value >> 16) as u16;
    out[11] = (o.uptime_s.value & 0xffff) as u16;
    out[12] = fw.as_u16();
    out[13] = faults;
    out[14] = MAP_VERSION;
    out
}

/// Holding registers, in address order. The node words read back the node
/// state, the `on_all` trigger reads 0, and register 9 is the result of
/// the last command word.
pub fn holding_registers(o: &Observed, last_result: ResultCode) -> [u16; HOLDING_COUNT] {
    let mut out = [0u16; HOLDING_COUNT];
    for (i, reg) in out[..NODE_COUNT].iter_mut().enumerate() {
        *reg = o.node_state((i + 1) as NodeId).as_modbus();
    }
    out[8] = 0;
    out[9] = last_result.as_u16();
    out
}

/// Coils, in address order: node power mirrors.
pub fn coils(o: &Observed) -> [bool; COIL_COUNT] {
    let mut out = [false; COIL_COUNT];
    for (i, bit) in out.iter_mut().enumerate() {
        *bit = matches!(o.node_state((i + 1) as NodeId), NodeState::On);
    }
    out
}

/// Turn a holding-register write into a command.
///
/// `Ok(None)` means the write is accepted and means "nothing to do"
/// (writing 0 to a node word clears it). `id` is the command id the
/// server invents, usually `modbus-<counter>`.
pub fn command_from_holding(addr: u16, value: u16, id: &str) -> Result<Option<Command>, MapError> {
    match addr {
        0..=7 => {
            let node = (addr + 1) as NodeId;
            let kind = match value {
                cmd_word::NONE => return Ok(None),
                cmd_word::ON => ActionKind::On,
                cmd_word::OFF => ActionKind::Off,
                cmd_word::FORCE_OFF => ActionKind::ForceOff,
                cmd_word::RESET => ActionKind::Reset,
                cmd_word::CYCLE => ActionKind::Cycle,
                _ => return Err(MapError::BadValue { addr, value }),
            };
            Ok(Some(
                Command::new(id, CommandKind::of_action(kind)).with_target(Target::Node(node)),
            ))
        }
        8 => match value {
            0 => Ok(None),
            1 => Ok(Some(
                Command::new(id, CommandKind::OnAll).with_target(Target::All),
            )),
            _ => Err(MapError::BadValue { addr, value }),
        },
        9 => Err(MapError::BadValue { addr, value }),
        _ => Err(MapError::UnknownRegister {
            kind: RegKind::HoldingRegister,
            addr,
        }),
    }
}

/// Turn a coil write into a command: 1 = `on`, 0 = `off`.
pub fn command_from_coil(addr: u16, on: bool, id: &str) -> Result<Option<Command>, MapError> {
    if addr as usize >= COIL_COUNT {
        return Err(MapError::UnknownRegister {
            kind: RegKind::Coil,
            addr,
        });
    }
    let node = (addr + 1) as NodeId;
    let kind = if on { ActionKind::On } else { ActionKind::Off };
    Ok(Some(
        Command::new(id, CommandKind::of_action(kind)).with_target(Target::Node(node)),
    ))
}

/// Default args a Modbus-born command carries: none. Modbus has no room
/// for `force`, so an `Unknown` node is refused exactly as it would be
/// over MQTT.
pub fn modbus_args() -> Args {
    Args::default()
}

/// Render the map as the Markdown document `firmware/docs/modbus_map.md`.
pub fn render_markdown() -> String {
    let mut s = String::new();
    s.push_str("# Granite controller Modbus map\n\n");
    s.push_str(&format!("Map version: {MAP_VERSION}\n\n"));
    s.push_str(
        "Generated from `granite-core/src/modbus_map.rs` (`render_markdown`). \
Do not edit by hand. Unit id and port are configuration (`sec.modbus`); \
the server is off by default and requires an allow-list.\n\n",
    );
    for kind in [
        RegKind::DiscreteInput,
        RegKind::InputRegister,
        RegKind::HoldingRegister,
        RegKind::Coil,
    ] {
        s.push_str(&format!("## {}\n\n", kind.as_str()));
        s.push_str("| Address | Name | Meaning | Scale | Access |\n");
        s.push_str("|---|---|---|---|---|\n");
        for e in MAP.iter().filter(|e| e.kind == kind) {
            s.push_str(&format!(
                "| {} | `{}` | {} | {} | {} |\n",
                e.addr,
                e.name,
                e.meaning,
                e.scale,
                e.access.as_str()
            ));
        }
        s.push('\n');
    }
    s.push_str("## Fault flags (input register 13)\n\n");
    s.push_str("| Bit | Meaning |\n|---|---|\n");
    for (bit, meaning) in [
        (
            fault_bits::EXPANDER,
            "expander readback mismatch or press deadline",
        ),
        (fault_bits::SENSE, "power LEDs unreadable"),
        (
            fault_bits::PROBE_MISSING,
            "a configured probe did not answer",
        ),
        (fault_bits::VIN, "bus voltage outside its window"),
        (
            fault_bits::OTA_PENDING,
            "an OTA image is pending validation",
        ),
        (
            fault_bits::CONFIG_FALLBACK,
            "a config section fell back to defaults",
        ),
        (fault_bits::MQTT_DOWN, "broker configured but not connected"),
    ] {
        s.push_str(&format!("| {} | {} |\n", bit.trailing_zeros(), meaning));
    }
    s.push('\n');
    s.push_str(
        "Writes to a node command word or a coil become the same `Command` \
the MQTT and HTTP paths use, so the refusal rules are identical: an action \
on a node whose state is `unknown` is refused, because Modbus cannot carry \
`force`.\n",
    );
    s
}

/// The map version as a string, for the documentation header and `/id`.
pub fn map_version_string() -> String {
    MAP_VERSION.to_string()
}
